import * as THREE from 'three';
const scene=new THREE.Scene();scene.background=new THREE.Color('#182744');const camera=new THREE.PerspectiveCamera(40,16/9,.1,100);camera.position.set(4,3,6);camera.lookAt(0,0,0);const renderer=new THREE.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});document.body.appendChild(renderer.domElement);document.body.style.margin='0';const mesh=new THREE.Mesh(new THREE.TorusKnotGeometry(1,.3,180,32),new THREE.MeshStandardMaterial({color:'#c7f0ad',metalness:.55,roughness:.24}));scene.add(mesh);scene.add(new THREE.HemisphereLight('#c4e8ff','#182234',3));const light=new THREE.DirectionalLight('#fff2b9',5);light.position.set(3,4,5);scene.add(light);window.renderStudio={version:1,render({width,height,pixelRatio,time}){renderer.setPixelRatio(pixelRatio);renderer.setSize(width/pixelRatio,height/pixelRatio);camera.aspect=width/height;camera.updateProjectionMatrix();mesh.rotation.y=time;renderer.render(scene,camera);renderer.getContext().finish();}};